// Generated by esquadro: do not edit. A resource's form: a field by its
// kind (or yours, from src/fields.ts), the API's refusals on their fields, a
// change on the version read (If-Match), a create sent once
// (Idempotency-Key), and a warning before leaving with changes unsaved.
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { useBlocker, useNavigate } from "@tanstack/react-router"
import { useMemo, useState } from "react"
import { fields as yours } from "@/fields.ts"
import { Button } from "@/components/ui/button.tsx"
import { Card } from "@/components/ui/card.tsx"
import { Input } from "@/components/ui/input.tsx"
import { api } from "../api.ts"
import { resources } from "../resources.gen.ts"
import { describe, fieldErrors } from "./errors.ts"
import { t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import type { Resource } from "./resource.ts"
import { useRecord } from "./show.tsx"
import { toast } from "./toast.tsx"

type Values = Record<string, unknown>

/** The input of a field, by its kind. */
export function FieldInput({ field, value, onChange }: { field: FieldMeta; value: unknown; onChange: (v: unknown) => void }) {
  const own = yours[field.name] ?? yours[field.kind]
  if (own?.input) return <>{own.input(value, onChange)}</>
  const str = value === null || value === undefined ? "" : String(value)
  switch (field.kind) {
    case "bool":
      return <input type="checkbox" checked={Boolean(value)} onChange={(e) => onChange(e.target.checked)} />
    case "textarea":
      return (
        <textarea
          className="min-h-24 w-full rounded-md border border-border bg-background p-2"
          value={str}
          onChange={(e) => onChange(e.target.value)}
        />
      )
    case "enum":
      return (
        <select
          className="w-full rounded-md border border-border bg-background px-2 py-2"
          value={str}
          onChange={(e) => onChange(e.target.value || null)}
        >
          <option value="" />
          {field.values?.map((v) => (
            <option key={v} value={v}>
              {v}
            </option>
          ))}
        </select>
      )
    case "relation":
      return <RelationInput field={field} value={str} onChange={onChange} />
    case "int":
      return <Input type="number" step="1" value={str} onChange={(e) => onChange(e.target.value === "" ? null : Number(e.target.value))} />
    case "decimal":
      return <Input inputMode="decimal" value={str} onChange={(e) => onChange(e.target.value === "" ? null : e.target.value)} />
    case "date":
      return <Input type="date" value={str.slice(0, 10)} onChange={(e) => onChange(e.target.value || null)} />
    case "datetime":
      return (
        <Input
          type="datetime-local"
          value={str ? str.slice(0, 16) : ""}
          onChange={(e) => onChange(e.target.value ? new Date(e.target.value).toISOString() : null)}
        />
      )
  }
  return <Input value={str} onChange={(e) => onChange(e.target.value === "" ? null : e.target.value)} />
}

/** A related record, picked from its resource's list. */
function RelationInput({ field, value, onChange }: { field: FieldMeta; value: string; onChange: (v: unknown) => void }) {
  const target = (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]
  const options = useQuery({
    queryKey: [field.target, "options"],
    queryFn: () => target.api(api as never).list({ per_page: 100, limit: 100 }),
    enabled: target !== undefined,
  })
  return (
    <select
      className="w-full rounded-md border border-border bg-background px-2 py-2"
      value={value}
      onChange={(e) => onChange(e.target.value || null)}
    >
      <option value="" />
      {options.data?.items.map((r: Rec) => (
        <option key={r.id} value={r.id}>
          {String(r[field.display ?? "id"] ?? r.id)}
        </option>
      ))}
    </select>
  )
}

function initial(fields: FieldMeta[], record?: Rec): Values {
  const out: Values = {}
  for (const f of fields) {
    if (!f.readOnly) out[f.name] = record ? record[f.name] ?? null : f.kind === "bool" ? false : null
  }
  return out
}

/** The form to create a record, or to change one (with its id). */
export function ResourceForm({ resource, id }: { resource: Resource; id?: string }) {
  const record = useRecord(resource, id)
  if (id !== undefined && record.isPending) return <div className="h-32 animate-pulse rounded-lg bg-muted" />
  if (record.isError) return <p className="text-destructive">{describe(record.error)}</p>
  return <Form resource={resource} record={record.data} />
}

function Form({ resource, record }: { resource: Resource; record?: Rec }) {
  const { meta } = resource
  const fields = resource.form.filter((f) => !f.readOnly)
  const [values, setValues] = useState<Values>(() => initial(fields, record))
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [dirty, setDirty] = useState(false)
  // One key for this form: sending it again (a double click, a retry)
  // creates the record once.
  const idempotencyKey = useMemo(() => crypto.randomUUID(), [])
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  useBlocker({ shouldBlockFn: () => dirty && !window.confirm(t("unsaved")), enableBeforeUnload: () => dirty })

  const save = useMutation({
    mutationFn: () =>
      record
        ? meta.api(api as never).update(record.id, values, { ifMatch: record })
        : meta.api(api as never).create(values, { idempotencyKey }),
    onSuccess: (saved: Rec) => {
      setDirty(false)
      toast(t("saved"))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
      setTimeout(() => navigate({ to: `/${meta.name}/${saved.id}` as never }))
    },
    onError: (e) => {
      setErrors(fieldErrors(e))
      toast(describe(e), "error")
    },
  })

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault()
        save.mutate()
      }}
    >
      <h1 className="text-xl font-semibold">{record ? t("editing", { name: meta.singular }) : t("creating", { name: meta.singular })}</h1>
      <Card className="flex flex-col gap-4">
        {fields.map((f) => (
          <label key={f.name} className="flex flex-col gap-1">
            <span className="text-sm font-medium">
              {f.label}
              {f.required && <span className="text-destructive"> *</span>}
            </span>
            <FieldInput
              field={f}
              value={values[f.name]}
              onChange={(v) => {
                setDirty(true)
                setValues((all) => ({ ...all, [f.name]: v }))
              }}
            />
            {errors[f.name] && <span className="text-sm text-destructive">{t("invalid", { code: errors[f.name] })}</span>}
          </label>
        ))}
      </Card>
      <div className="flex gap-2">
        <Button type="submit" disabled={save.isPending}>
          {t("save")}
        </Button>
        <Button type="button" variant="outline" onClick={() => history.back()}>
          {t("cancel")}
        </Button>
      </div>
    </form>
  )
}
